    @JvmField var soilInfil: TGrnAmpt? = TGrnAmpt()
    @JvmField var surfaceDepth: Double = 0.0
    @JvmField var paveDepth: Double = 0.0
    @JvmField var soilMoisture: Double = 0.0
    @JvmField var storageDepth: Double = 0.0
    @JvmField var oldFluxRates: DoubleArray? = DoubleArray(4)
    @JvmField var dryTime: Double = 0.0
    @JvmField var oldDrainFlow: Double = 0.0
    @JvmField var newDrainFlow: Double = 0.0
    @JvmField var volTreated: Double = 0.0
    @JvmField var nextRegenDay: Double = 0.0
    @JvmField var waterBalance: TWaterBalance? = TWaterBalance()
    fun copy(): TLidUnit {
        val c = TLidUnit()
        c.lidIndex = lidIndex
        c.number = number
        c.area = area
        c.fullWidth = fullWidth
        c.botWidth = botWidth
        c.initSat = initSat
        c.fromImperv = fromImperv
        c.fromPerv = fromPerv
        c.toPerv = toPerv
        c.drainSubcatch = drainSubcatch
        c.drainNode = drainNode
        c.rptFile = rptFile
        c.soilInfil = soilInfil!!.copy()
        c.surfaceDepth = surfaceDepth
        c.paveDepth = paveDepth
        c.soilMoisture = soilMoisture
        c.storageDepth = storageDepth
        c.oldFluxRates = oldFluxRates!!.clone()
        c.dryTime = dryTime
        c.oldDrainFlow = oldDrainFlow
        c.newDrainFlow = newDrainFlow
        c.volTreated = volTreated
        c.nextRegenDay = nextRegenDay
        c.waterBalance = waterBalance!!.copy()
        return c
    }
}

